INSERT INTO `scholarships` VALUES (1,'ACAD_FULL','Full Academic Scholarship','Full tuition waiver for academic excellence','percentage',100.00,'tuition',1,'2026-01-30 14:34:11','2026-01-30 14:34:11'),(2,'ACAD_HALF','Half Academic Scholarship','50% tuition discount for academic excellence','percentage',50.00,'tuition',1,'2026-01-30 14:34:11','2026-01-30 14:34:11'),(3,'ACAD_25','Partial Academic Scholarship','25% tuition discount','percentage',25.00,'tuition',1,'2026-01-30 14:34:11','2026-01-30 14:34:11'),(4,'SIBLING','Sibling Discount','10% discount for siblings enrolled','percentage',10.00,'tuition',1,'2026-01-30 14:34:11','2026-01-30 14:34:11'),(5,'ALUMNI','Alumni Dependent Discount','15% discount for children of alumni','percentage',15.00,'tuition',1,'2026-01-30 14:34:11','2026-01-30 14:34:11'),(6,'ATHLETE','Athletic Scholarship','Full scholarship for varsity athletes','percentage',100.00,'all',1,'2026-01-30 14:34:11','2026-01-30 14:34:11'),(7,'FINANCIAL_AID','Financial Assistance','Need-based financial aid','percentage',50.00,'all',1,'2026-01-30 14:34:11','2026-01-30 14:34:11'),(8,'EMPLOYEE','Employee Dependent','Free tuition for employee dependents','percentage',100.00,'tuition',1,'2026-01-30 14:34:11','2026-01-30 14:34:11'),(9,'MERIT_25','Merit Scholarship 25%','Auto-awarded on promotion when best final grade is 1.75 or better and no passed final grade is 2.00 or higher.','percentage',25.00,'tuition',1,'2026-03-22 04:36:28','2026-03-23 13:10:21'),(10,'MERIT_50','Merit Scholarship 50%','Auto-awarded on promotion when all passed final grades in source term are 1.50 or better.','percentage',50.00,'tuition',1,'2026-03-22 04:36:28','2026-03-23 13:10:21'),(13,'MERIT_75','Merit Scholarship 75%','Auto-awarded on promotion when all passed final grades in source term are 1.25 or better.','percentage',75.00,'tuition',1,'2026-03-22 04:58:57','2026-03-23 13:10:21');
